// Demo: Ephemeral ECDHE Handshakes — HKDF-style key rotation chain
function hkdf(prev){var h=0;var s='rot'+prev;for(var i=0;i<s.length;i++){h=(h*31+s.charCodeAt(i))>>>0;}return h.toString(16);}
var k='seed-1';var chain=[k];
for(var i=0;i<5;i++){k=hkdf(k);chain.push(k);}
console.log('technique: Ephemeral ECDHE Handshakes');console.log('key chain: '+chain.join(' -> '));
console.log('compromise of key 3 reveals nothing about keys 0-2 (one-way)');

